/**
 * Characterisation of syncProjectTypes (before PB-6): which route paths and route-component
 * selectors a route table yields, where the generated files go, and which old files are removed.
 */
import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { syncProjectTypes } from './router-typegen.js';

const page = (...names: string[]): string =>
  `import { defineComponent } from 'thane';\n` +
  names.map((n) => `export const ${n} = defineComponent(() => ({ template: html\`<p>${n}</p>\` }));\n`).join('');

const TSCONFIG = '{ "compilerOptions": { "strict": true } }';

const FILES: Record<string, string> = {
  'tsconfig.json': TSCONFIG,
  'src/pages/home.ts': page('HomePage'),
  'src/pages/about.ts': `import { defineComponent } from 'thane';\nexport const AboutPage = defineComponent('about-view', () => ({ template: html\`<p>a</p>\` }));\n`,
  'src/pages/multi.ts': page('FirstPage', 'SecondPage'),
  'src/pages/lazy.ts': page('LazyPage'),
  'src/pages/user.ts': page('UserPage'),
  'src/pages/folder/index.ts': page('FolderPage'),
  'src/routes.ts': `
import { defineRoutes } from 'thane/router';
import { HomePage as Home } from './pages/home.js';
import Multi from './pages/multi.js';
import { External } from 'some-package';

const extra = {};

export const Routes = defineRoutes({
  '/': { component: Home },
  '/about': { component: () => import('./pages/about.js').then((m) => m.AboutPage) },
  '/multi': { component: Multi },
  '/lazy': { componentModule: () => import('./pages/lazy') },
  '/folder': { component: () => import('./pages/folder') },
  '/users/:id': { component: () => import('./pages/user.js').then((m) => m.UserPage), title: 'User' },
  '/ext': { component: External },
  '/missing': { component: () => import('./pages/nope.js').then((m) => m.Nope) },
  "/it's": { component: Home },
  ...extra,
  notFound: { component: () => import('./pages/home.js').then((m) => m.HomePage) },
});
`,
  // Two tables in one file: their paths share one union, their selectors one map
  'src/other-routes.ts': `
import { defineRoutes } from 'thane/router';
import { UserPage } from './pages/user.js';
export const A = defineRoutes({ '/a1': { component: UserPage }, '/a2': { component: () => import('./pages/multi.js').then((m) => m.FirstPage) } });
export const B = defineRoutes({ '/b1': { component: () => import('./pages/lazy.js') }, '/b2': {} });
`,
  // Mentions defineRoutes( but has no table literal: no file
  'src/indirect.ts': `import { defineRoutes } from 'thane/router';\nconst table = {};\nexport const R = defineRoutes(table);\n`,
  // A second project with its own tsconfig
  'nested/tsconfig.json': TSCONFIG,
  'nested/src/n.ts': page('NestedPage'),
  'nested/src/routes.ts': `import { defineRoutes } from 'thane/router';\nimport { NestedPage } from './n.js';\nexport default defineRoutes({ '/n': { component: NestedPage } });\n`,
  // Old files that a sync removes
  'src/__thane-router.generated.d.ts': 'export {};\n',
  '.thane/types/router/src/old.generated.d.ts': 'export {};\n',
  '.thane/router-types/x.d.ts': 'export {};\n',
};

const EXPECTED_ROUTES = `/* Auto-generated by Thane. Do not edit by hand. */
declare global {
  namespace ThaneTypeRegistry {
    interface Register {
      routePaths: '/' | '/about' | '/multi' | '/lazy' | '/folder' | '/users/:id' | '/ext' | '/missing' | '/it\\'s';
    }

    interface RouteComponentRegister {
    'about-view': '/about';
    'folder-page': '/folder';
    'home-page': 'notFound';
    'lazy-page': '/lazy';
    'second-page': '/multi';
    'user-page': '/users/:id';
    }
  }
}

export {};
`;

let root = '';
let count = 0;
const generated = (...parts: string[]) => join(root, ...parts);

beforeAll(async () => {
  root = mkdtempSync(join(tmpdir(), 'thane-typegen-'));
  for (const [file, text] of Object.entries(FILES)) {
    mkdirSync(dirname(join(root, file)), { recursive: true });
    writeFileSync(join(root, file), text);
  }
  count = await syncProjectTypes(root);
});

afterAll(() => {
  rmSync(root, { recursive: true, force: true });
});

describe('syncProjectTypes', () => {
  test('counts one generated file per file with a route table literal', () => {
    expect(count).toBe(3);
    expect(existsSync(generated('.thane', 'types', 'router', 'src', 'indirect.generated.d.ts'))).toBe(false);
  });

  test('route paths in source order; selectors from named, renamed, default and lazy imports', () => {
    expect(readFileSync(generated('.thane', 'types', 'router', 'src', 'routes.generated.d.ts'), 'utf8')).toBe(
      EXPECTED_ROUTES,
    );
  });

  test('two tables in one file share one union and one selector map', () => {
    const text = readFileSync(generated('.thane', 'types', 'router', 'src', 'other-routes.generated.d.ts'), 'utf8');
    const union = /routePaths: (.*);/.exec(text)?.[1] ?? '';
    expect(union.split(' | ').sort()).toEqual(["'/a1'", "'/a2'", "'/b1'", "'/b2'"]);
    expect(text.replace(/routePaths: .*;/, 'routePaths: X;')).toBe(
      EXPECTED_ROUTES.replace(/routePaths: .*;/, 'routePaths: X;').replace(
        /interface RouteComponentRegister \{\n[\s\S]*?\n {4}\}/,
        "interface RouteComponentRegister {\n    'first-page': '/a2';\n    'lazy-page': '/b1';\n    'user-page': '/a1';\n    }",
      ),
    );
  });

  test('a nested project gets its own generated folder', () => {
    expect(
      readFileSync(join(root, 'nested', '.thane', 'types', 'router', 'src', 'routes.generated.d.ts'), 'utf8'),
    ).toContain(`routePaths: '/n';`);
    expect(existsSync(join(root, 'nested', '.thane', 'types', 'client.d.ts'))).toBe(true);
    expect(existsSync(generated('.thane', 'types', 'router', 'nested'))).toBe(false);
  });

  test('client types are copied from the package', () => {
    const packaged = readFileSync(resolve(import.meta.dir, '../../../../client.d.ts'), 'utf8');
    expect(readFileSync(generated('.thane', 'types', 'client.d.ts'), 'utf8')).toBe(packaged);
  });

  test('legacy and stale generated files are removed', () => {
    expect(existsSync(generated('src', '__thane-router.generated.d.ts'))).toBe(false);
    expect(existsSync(generated('.thane', 'types', 'router', 'src', 'old.generated.d.ts'))).toBe(false);
    expect(existsSync(generated('.thane', 'router-types'))).toBe(false);
  });

  test('a second sync leaves unchanged files alone', async () => {
    const file = generated('.thane', 'types', 'router', 'src', 'routes.generated.d.ts');
    const before = statSync(file).mtimeMs;
    await Bun.sleep(20);
    expect(await syncProjectTypes(root)).toBe(3);
    expect(statSync(file).mtimeMs).toBe(before);
    expect(readFileSync(file, 'utf8')).toBe(EXPECTED_ROUTES);
  });
});
